; ==============================================================
; Bank 80 ($50)  file offset $140000-$143FFF
; MAIN GAME STATE ORCHESTRATOR
;   Central hub called from ROM0 vblank/game loop.
;   Manages top-level game state transitions and delegates to
;   sub-banks (bank2, bank23, bank81…) for specific screens.
;
; WRAM layout (key addresses observed in this bank):
;   $C827      - zero'd 0x12 bytes on reset (screen state?)
;   $C83E:C83F - VRAM tilemap ptr ($99C1 on init)
;   $C850      - "busy/locked" flag (if non-zero, many fns skip)
;   $C86C      - input/joypad activity flag
;   $C87E      - cleared on reset
;   $C8DA      - zero'd 8 bytes on reset (display state?)
;   $C8EC      - cleared on reset
;   $DA79:DA7A - saved SP on fn0 entry
;   $DA80      - action mode selector (fn2 reads 0x01 = battle?)
;   $DA81      - action parameter (e.g. monster/party slot)
;   $D9EC      - zero'd 8 bytes on reset (multi-state vars)
;   $D9F4      - zero'd 8 bytes on reset
;   $D9ED      - main state index for RST $00 dispatch
;   $DD60      - cleared on reset
;   $DD62      - something written to by ROM0 $1637
;
; 11 functions via RST $10:
;   fn0   → $4017  reset/init: zero WRAM, call screen_init, call bank81 fn0
;   fn1   → $406F  main tick: joypad check → bank2 fn0 (DI-protected)
;   fn2   → $4097  action dispatch: reads DA80/DA81, delegates to bank23
;   fn3   → $42A1  presentation: setup + win/loss branch on $DA88
;   fn4   → $7315  slot range check: validates battle target index
;   fn5   → $6D56  bulk DMA: 0x12 rows × 0x20 bytes → WRAM $C500
;   fn6   → $70B3  battle-side data display (HP/name via $DB region)
;   fn7   → $69D8  monster action dispatch (attack / special / skip)
;   fn8   → $6B4B  battle round setup: sprites, tilemap, zero round vars
;   fn9   → $742E  party scan: count active queued members in $DD1B
;   fn10  → $746A  battle participant iterator: 3 slots, one side
; RST $00 at $0000: state-dispatch (A=index, DW table follows instruction)
; ==============================================================
SECTION "bank80",ROMX[$4017],BANK[$50]


; Reset/initialize main game state:
;   save SP, zero WRAM regions, set VRAM tilemap ptr,
;   call screen_init, then kick bank81 fn0 (sub-screen init).
Bank80_fn0:  ; $4017
    LD HL,SP+0                             ; $4017 [F8 00]
    LD A,L                                 ; $4019 [7D]
    LD ($DA79),A                           ; $401A [EA 79 DA]  ; → WRAM[$DA79]
    LD A,H                                 ; $401D [7C]
    LD ($DA7A),A                           ; $401E [EA 7A DA]  ; → WRAM[$DA7A]
    XOR A                                  ; $4021 [AF]
    LD HL,$C8DA                            ; $4022 [21 DA C8]
    LD BC,$0008                            ; $4025 [01 08 00]
    CALL $169A                             ; $4028 [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    XOR A                                  ; $402B [AF]
    LD HL,$C827                            ; $402C [21 27 C8]
    LD BC,$0012                            ; $402F [01 12 00]
    CALL $169A                             ; $4032 [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    LD HL,$99C1                            ; $4035 [21 C1 99]
    LD A,L                                 ; $4038 [7D]
    LD ($C83E),A                           ; $4039 [EA 3E C8]  ; → WRAM[$C83E]
    LD A,H                                 ; $403C [7C]
    LD ($C83F),A                           ; $403D [EA 3F C8]  ; → WRAM[$C83F]
    XOR A                                  ; $4040 [AF]
    LD HL,$D9EC                            ; $4041 [21 EC D9]
    LD BC,$0008                            ; $4044 [01 08 00]
    CALL $169A                             ; $4047 [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    XOR A                                  ; $404A [AF]
    LD HL,$D9F4                            ; $404B [21 F4 D9]
    LD BC,$0008                            ; $404E [01 08 00]
    CALL $169A                             ; $4051 [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    XOR A                                  ; $4054 [AF]
    LD ($D9ED),A                           ; $4055 [EA ED D9]  ; → WRAM[$D9ED]
    LD ($DD62),A                           ; $4058 [EA 62 DD]  ; → WRAM[$DD62]
    CALL $1637                             ; $405B [CD 37 16]  ; screen_init
    XOR A                                  ; $405E [AF]
    LD ($DD60),A                           ; $405F [EA 60 DD]  ; → WRAM[$DD60]
    XOR A                                  ; $4062 [AF]
    LD ($C8EC),A                           ; $4063 [EA EC C8]  ; → WRAM[$C8EC]
    XOR A                                  ; $4066 [AF]
    LD ($C87E),A                           ; $4067 [EA 7E C8]  ; → WRAM[$C87E]
    LD HL,$5100                            ; $406A [21 00 51]
    RST $10                                ; $406D [D7]  ; bankcall → bank81 fn0
    RET                                    ; $406E [C9]

; Main game loop tick:
;   If $C86C (joypad active): handle input via ROM0 $043E.
;   If not busy ($C850==0): call ROM0 $33D0 (frame update?).
;   If $DD62 set: DI → bank2 fn0 → EI (critical section).
Bank80_fn1:  ; $406F
    LD A,($C86C)                           ; $406F [FA 6C C8]  ; WRAM[$C86C]
    OR A                                   ; $4072 [B7]
    JR Z,$408C                             ; $4073 [28 17]
    CALL $043E                             ; $4075 [CD 3E 04]  ; ROM0 $043E
    LD A,($C850)                           ; $4078 [FA 50 C8]  ; WRAM[$C850]
    OR A                                   ; $407B [B7]
    RET NZ                                 ; $407C [C0]
    CALL $33D0                             ; $407D [CD D0 33]  ; ROM0 $33D0
    LD A,($DD62)                           ; $4080 [FA 62 DD]  ; WRAM[$DD62]
    OR A                                   ; $4083 [B7]
    RET Z                                  ; $4084 [C8]
    DI                                     ; $4085 [F3]
    LD HL,$0200                            ; $4086 [21 00 02]
    RST $10                                ; $4089 [D7]  ; bankcall → bank2 fn0
    EI                                     ; $408A [FB]
    RET                                    ; $408B [C9]
.lbl_408C:
    LD A,($C850)                           ; $408C [FA 50 C8]  ; WRAM[$C850]
    OR A                                   ; $408F [B7]
    RET NZ                                 ; $4090 [C0]
    CALL $33D0                             ; $4091 [CD D0 33]  ; ROM0 $33D0
    CALL $4FD1                             ; $4094 [CD D1 4F]

; ==============================================================
; fn2 — ACTION / SCENE DISPATCHER  (the bank's real workhorse)
; ==============================================================
;   Runs once per frame. WRAM[$DA80] is a 3-value phase selector:
;     $DA80 == 1 : "load" phase — copy the graphic selected by $DA81
;                  into VRAM $8000, then bump $DA80 to 2 and return.
;     $DA80 == 2 : "run" phase  — service any pending bank2 work
;                  ($DD62 flag), then clear $DA80 back to 0.
;     $DA80 == 0 : "idle/main" phase ($4147) — runs the 18-state
;                  scene sequencer keyed on WRAM[$D9EC].
;   Guarded at the top by $C850 (global busy lock).
; --------------------------------------------------------------
Bank80_fn2:  ; $4097
    LD A,($C850)                           ; $4097 [FA 50 C8]  ; WRAM[$C850]  busy lock
    OR A                                   ; $409A [B7]
    RET NZ                                 ; $409B [C0]         ; locked → do nothing this frame
    LD A,($DA80)                           ; $409C [FA 80 DA]  ; WRAM[$DA80]  phase selector
    CP $01                                 ; $409F [FE 01]
    JP NZ,$412C                            ; $40A1 [C2 2C 41]   ; phase ≠ 1 → run/idle handler
    ; --- phase 1: load the graphic for action id $DA81 ---
    LD A,($DA81)                           ; $40A4 [FA 81 DA]  ; WRAM[$DA81]  action / icon id
    CP $FF                                 ; $40A7 [FE FF]
    RET Z                                  ; $40A9 [C8]         ; $FF = no action → bail
    LD A,($DA81)                           ; $40AA [FA 81 DA]  ; WRAM[$DA81]
    LD ($C81E),A                           ; $40AD [EA 1E C8]  ; → WRAM[$C81E]  publish id for sub-banks
    LD HL,$170D                            ; $40B0 [21 0D 17]
    RST $10                                ; $40B3 [D7]  ; bankcall → bank23 fn13  (prep window)
    LD HL,$1708                            ; $40B4 [21 08 17]
    RST $10                                ; $40B7 [D7]  ; bankcall → bank23 fn8   (draw frame)
    ; look up source pointer from ptr table (see $40D2) by id, copy to VRAM
    LD A,($DA81)                           ; $40B8 [FA 81 DA]  ; WRAM[$DA81]
    LD HL,$40D2                            ; $40BB [21 D2 40]  ; base of source-pointer table
    LD C,A                                 ; $40BE [4F]
    LD B,$00                               ; $40BF [06 00]
    ADD HL,BC                              ; $40C1 [09]         ; HL = $40D2 + id
    ADD HL,BC                              ; $40C2 [09]         ; HL = $40D2 + 2*id  (word stride)
    LDI A,(HL)                             ; $40C3 [2A]         ; DE = table[id] (source ptr)
    LD D,(HL)                              ; $40C4 [56]
    LD E,A                                 ; $40C5 [5F]
    LD HL,$8000                            ; $40C6 [21 00 80]  ; dest = VRAM tile area $8000
    CALL $194A                             ; $40C9 [CD 4A 19]  ; ROM0 $194A  copy(DE→HL)
    LD A,$02                               ; $40CC [3E 02]
    LD ($DA80),A                           ; $40CE [EA 80 DA]  ; → WRAM[$DA80]  advance to phase 2
    RET                                    ; $40D1 [C9]
    ; --- DATA (not code): source-pointer table for fn2 ---
    ;   Indexed by WRAM[$DA81] (action / icon id). ADD HL,BC twice
    ;   at $40C1 gives HL = $40D2 + 2*id; the 2-byte entry is loaded
    ;   into DE and passed to ROM0 $194A (copy → VRAM $8000).
    ;   idx 0-31 -> $5A00..$5A1F   idx 32-44 -> $5B0A..$5B16
Bank80_fn2_ptrtab:  ; $40D2
    DW $5A00,$5A01,$5A02,$5A03,$5A04,$5A05,$5A06,$5A07  ; idx 0-7
    DW $5A08,$5A09,$5A0A,$5A0B,$5A0C,$5A0D,$5A0E,$5A0F  ; idx 8-15
    DW $5A10,$5A11,$5A12,$5A13,$5A14,$5A15,$5A16,$5A17  ; idx 16-23
    DW $5A18,$5A19,$5A1A,$5A1B,$5A1C,$5A1D,$5A1E,$5A1F  ; idx 24-31
    DW $5B0A,$5B0B,$5B0C,$5B0D,$5B0E,$5B0F,$5B10,$5B11  ; idx 32-39
    DW $5B12,$5B13,$5B14,$5B15,$5B16  ; idx 40-44
; --- phase 2 ("run") + idle fall-through ---
;   If a bank2 job is queued ($DD62≠0) and joypad is idle, execute it
;   (bank2 fn0) as a critical background step; once it clears $DD62,
;   drop $DA80 to 0 (back to idle). If nothing queued, go straight to
;   the main sequencer at $4147.
.lbl_412C:
    LD A,($DD62)                           ; $412C [FA 62 DD]  ; WRAM[$DD62]  pending-job flag
    OR A                                   ; $412F [B7]
    JR Z,$4147                             ; $4130 [28 15]      ; nothing queued → main sequencer
    LD A,($C86C)                           ; $4132 [FA 6C C8]  ; WRAM[$C86C]  joypad activity
    OR A                                   ; $4135 [B7]
    JR NZ,$413C                            ; $4136 [20 04]      ; input pending → skip job this frame
    LD HL,$0200                            ; $4138 [21 00 02]
    RST $10                                ; $413B [D7]  ; bankcall → bank2 fn0  (run queued job)
.lbl_413C:
    LD A,($DD62)                           ; $413C [FA 62 DD]  ; WRAM[$DD62]
    OR A                                   ; $413F [B7]
    RET NZ                                 ; $4140 [C0]         ; job still running → stay in phase 2
    LD A,$00                               ; $4141 [3E 00]
    LD ($DA80),A                           ; $4143 [EA 80 DA]  ; → WRAM[$DA80]  job done → idle
    RET                                    ; $4146 [C9]
; --- MAIN SEQUENCER entry ---
;   Pre-gate: unless $D9EC==$0D, if a text/message box is active
;   ($C825≠0) and $DA82 flags a pending prompt, pump the message
;   engine (bank95 fn5) and return early — the sequencer is paused
;   while text is on screen.
.lbl_4147:
    LD A,($D9EC)                           ; $4147 [FA EC D9]  ; WRAM[$D9EC]  scene state index
    CP $0D                                 ; $414A [FE 0D]
    JR Z,$4165                             ; $414C [28 17]      ; state 13 bypasses text gate
    LD A,($C825)                           ; $414E [FA 25 C8]  ; WRAM[$C825]  message-box active?
    OR A                                   ; $4151 [B7]
    JR Z,$4165                             ; $4152 [28 11]      ; no box → run sequencer
    LD A,($DA82)                           ; $4154 [FA 82 DA]  ; WRAM[$DA82]  prompt pending?
    OR A                                   ; $4157 [B7]
    JR Z,$4165                             ; $4158 [28 0B]
    LD HL,$5F05                            ; $415A [21 05 5F]
    RST $10                                ; $415D [D7]  ; bankcall → bank95 fn5  (advance text)
.lbl_415E:
    LD A,($C87E)                           ; $415E [FA 7E C8]  ; WRAM[$C87E]  text-done flag
    OR A                                   ; $4161 [B7]
    JR NZ,$4165                            ; $4162 [20 01]      ; text finished → run sequencer
    RET                                    ; $4164 [C9]         ; still printing → wait
.lbl_4165:
    LD A,($DA82)                           ; $4165 [FA 82 DA]  ; WRAM[$DA82]
    OR A                                   ; $4168 [B7]
    JR Z,$417D                             ; $4169 [28 12]
    LD A,($DA83)                           ; $416B [FA 83 DA]  ; WRAM[$DA83]  prompt sub-type
    CP $09                                 ; $416E [FE 09]
    JR NZ,$417D                            ; $4170 [20 0B]
    LD HL,$5F05                            ; $4172 [21 05 5F]
    RST $10                                ; $4175 [D7]  ; bankcall → bank95 fn5  (special prompt #9)
    LD A,($C87E)                           ; $4176 [FA 7E C8]  ; WRAM[$C87E]
    OR A                                   ; $4179 [B7]
    JR NZ,$417D                            ; $417A [20 01]
    RET                                    ; $417C [C9]
; ==============================================================
; BATTLE-SCENE SEQUENCER  ($D9EC, 18 states)  — the outer machine
; ==============================================================
;   $DB73==$FF means "no scene running" → jump to the wind-down at $41AC.
;   Otherwise dispatch on $D9EC. This is the TOP-level battle flow; the
;   command phase ($D9F4) and damage resolution ($D9ED) are sub-machines
;   nested inside individual states here.
;
;   NOTE: this is NOT a clean 0→17 march. Several advances happen inside
;   OTHER banks (so there is no $D9EC write here to see), and there are
;   non-linear jumps. States 0/1 are a short separate sub-flow (gated on
;   $CA8D); the battle proper is entered at state 2/3 by the caller.
;
;   STATE ROLES:
;     0  $41BB  OPEN        build battle window (bank23), init
;     1  $41E1  WAIT        block on msg box, tick $DA33; then draw/teardown
;     2  $41FC  SETUP       layout/data prep, reset sub-cursor
;     3  $420F  POPULATE    build per-monster action list from $DD03
;     4  $429F  COMMAND     run $5017 (the $D9F4 command-select machine)
;     5  $42BD  SUB-SCREEN  hand off to bank88 fn0
;     6  $42C7  NORMALIZE   clear counters, remap scene pointer $C1ED
;     7  $4304  RENDER      draw battle panel via bank82 fn0
;     8  $4319  SETTLE      5-frame delay, then start damage resolution
;     9  $4D05  DAMAGE      nested 6-step machine on $D9ED
;    10  $433B  RESULT      present outcome / draw result window
;    11  $453E  WAIT-ANIM   wait for attack anims $CA8E/8F/90 to finish
;    12  $460F  TURN        run bank81 fn12 (per-turn execution)
;    13  $4620  MSG-QUEUE   flush queued battle messages $DD61
;    14  $4658  TEARDOWN    restore prior screen (bank1 fn6), mark over
;    15  $4B9F  (unused)    RET only; reserved slot
;    16  $482A  SET-FLAG    raise $C873, then advance
;    17  $4834  PERSIST     save battle result to SRAM (link confirm)
;
;   TRANSITIONS (verified from the $D9EC writes; ✓=INC, →N=direct write):
;      0 OPEN      INC $41CF/$41DC              -> 1
;      1 WAIT      when done & $CA8D==0: runs 14's code (no $D9EC write)
;      2 SETUP     INC $4205                    -> 3
;      3 POPULATE  INC $4212                    -> 4
;      4 COMMAND   cmd phase INCs at its st.8 ($53C2)      -> 5
;      5 SUBSCREEN bank88 fn0 advances when done           -> 6
;      6 NORMALIZE INC $42CA (falls through)     -> 7
;      7 RENDER    bank82 fn0 advances to 8 when anim done -> 8
;      8 SETTLE    INC $4327 + JP $4D05          -> 9
;      9 DAMAGE    $D9EC=$0A $4F1E -> 10  |  $D9EC=$03 $4FC5 -> 3 (round loop)
;     10 RESULT    INC $439B -> 11        |  $D9EC=$10 $4381 -> 16 (link save)
;     11 WAIT-ANIM INC $455B                     -> 12
;     12 TURN      stays while $DB55==0 (bank81) | $D9EC=$0E $461C -> 14
;     13 MSGQUEUE  INC $4633                     -> 14
;     14 TEARDOWN  ends scene; hands back to caller
;     16 SET-FLAG  INC $482F                     -> 17
;     17 PERSIST   ends
;      (a command handler at $67FF can also force $D9EC=$0A -> 10)
;
;   MACRO-FLOW (the battle round loop):
;     OPEN -> SETUP(2,3) -> COMMAND(4) -> SUBSCREEN(5) -> NORMALIZE(6)
;       -> RENDER(7) -> SETTLE(8) -> DAMAGE(9) --+-- loop->3 (more actors)
;                                                +-- RESULT(10) -> WAITANIM(11)
;       -> TURN(12) -> MSGQUEUE(13) -> TEARDOWN(14)
;       [link battle: RESULT(10) -> SET(16) -> PERSIST/save(17)]
; --------------------------------------------------------------
.lbl_417D:
    LD A,($DB73)                           ; $417D [FA 73 DB]  ; WRAM[$DB73]  active-scene id ($FF=none)
    CP $FF                                 ; $4180 [FE FF]
    JR Z,$41AC                             ; $4182 [28 28]      ; no scene → cleanup path
    LD A,($D9EC)                           ; $4184 [FA EC D9]  ; WRAM[$D9EC]  step index (0..17)
    RST $00                                ; $4187 [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (18 scene steps, keyed by WRAM[$D9EC]):
    DW $41BB    ; $4188 [BB 41]  state 0  — open: bank23 window setup, then advance
    DW $41E1    ; $418A [E1 41]  state 1  — wait for $C825 clear, then $DA33 timer
    DW $41FC    ; $418C [FC 41]  state 2
    DW $420F    ; $418E [0F 42]  state 3
    DW $429F    ; $4190 [9F 42]  state 4
    DW $42BD    ; $4192 [BD 42]  state 5  — kick bank88 fn0 (sub-screen) when idle
    DW $42C7    ; $4194 [C7 42]  state 6  — advance $D9EC, clear scratch, latch $C1ED ptr
    DW $4304    ; $4196 [04 43]  state 7
    DW $4319    ; $4198 [19 43]  state 8
    DW $4D05    ; $419A [05 4D]  state 9
    DW $433B    ; $419C [3B 43]  state 10
    DW $453E    ; $419E [3E 45]  state 11
    DW $460F    ; $41A0 [0F 46]  state 12
    DW $4620    ; $41A2 [20 46]  state 13
    DW $4658    ; $41A4 [58 46]  state 14
    DW $4B9F    ; $41A6 [9F 4B]  state 15
    DW $482A    ; $41A8 [2A 48]  state 16
    DW $4834    ; $41AA [34 48]  state 17
; Scene wind-down: when no scene is active, AND $DD80 with mask $DD9A;
;   only when all masked bits are set ($FF) reset $DB73 back to $FF.
.lbl_41AC:
    LD A,($DD80)                           ; $41AC [FA 80 DD]  ; WRAM[$DD80]
    LD HL,$DD9A                            ; $41AF [21 9A DD]
    AND (HL)                               ; $41B2 [A6]
    CP $FF                                 ; $41B3 [FE FF]
    RET NZ                                 ; $41B5 [C0]
    XOR A                                  ; $41B6 [AF]
    LD ($DB73),A                           ; $41B7 [EA 73 DB]  ; → WRAM[$DB73]
    RET                                    ; $41BA [C9]
; STATE 0 ($41BB) — OPEN SCENE:
;   Build the base window (bank23 fn2 = clear, fn8 = draw frame).
;   If tab/page index $CA8D==0 (first page): run ROM0 $0D5A (init helper,
;   arg $0C00) and advance $D9EC → state 1.
;   Otherwise ($CA8D≠0) take the $41D4 branch: prep via $4BC2, arm a
;   5-frame delay in $DA33, then advance $D9EC → state 1.
.lbl_41BB:
    LD HL,$1702                            ; $41BB [21 02 17]
    RST $10                                ; $41BE [D7]  ; bankcall → bank23 fn2  (clear window)
    LD HL,$1708                            ; $41BF [21 08 17]
    RST $10                                ; $41C2 [D7]  ; bankcall → bank23 fn8  (draw frame)
    LD A,($CA8D)                           ; $41C3 [FA 8D CA]  ; WRAM[$CA8D]  page index
    OR A                                   ; $41C6 [B7]
    JR NZ,$41D4                            ; $41C7 [20 0B]      ; not first page → delayed path
    LD HL,$0C00                            ; $41C9 [21 00 0C]
    CALL $0D5A                             ; $41CC [CD 5A 0D]  ; ROM0 $0D5A  (init helper)
    LD HL,$D9EC                            ; $41CF [21 EC D9]
    INC (HL)                               ; $41D2 [34]         ; advance → state 1
    RET                                    ; $41D3 [C9]
.lbl_41D4:
    CALL $4BC2                             ; $41D4 [CD C2 4B]
    LD A,$05                               ; $41D7 [3E 05]
    LD ($DA33),A                           ; $41D9 [EA 33 DA]  ; → WRAM[$DA33]
    LD HL,$D9EC                            ; $41DC [21 EC D9]
    INC (HL)                               ; $41DF [34]
    RET                                    ; $41E0 [C9]
; STATE 1 ($41E1) — WAIT / COUNTDOWN:
;   Block while a message box is up ($C825≠0). Then tick down the
;   $DA33 delay counter (return each frame until it hits 0).
;   When elapsed: if page $CA8D==0 jump to state-14 handler ($4658);
;   otherwise call $4C12 (page-specific draw) and stay.
.lbl_41E1:
    LD A,($C825)                           ; $41E1 [FA 25 C8]  ; WRAM[$C825]  message box up?
    OR A                                   ; $41E4 [B7]
    RET NZ                                 ; $41E5 [C0]         ; wait for box to close
    LD A,($DA33)                           ; $41E6 [FA 33 DA]  ; WRAM[$DA33]  delay counter
    OR A                                   ; $41E9 [B7]
.lbl_41EA:
    JR Z,$41F1                             ; $41EA [28 05]      ; delay done
    DEC A                                  ; $41EC [3D]
    LD ($DA33),A                           ; $41ED [EA 33 DA]  ; → WRAM[$DA33]  tick down
    RET                                    ; $41F0 [C9]
.lbl_41F1:
    LD A,($CA8D)                           ; $41F1 [FA 8D CA]  ; WRAM[$CA8D]  page index
    OR A                                   ; $41F4 [B7]
    JP Z,$4658                             ; $41F5 [CA 58 46]   ; first page → state-14 handler
    CALL $4C12                             ; $41F8 [CD 12 4C]   ; else page-specific draw
    RET                                    ; $41FB [C9]
; STATE 2 ($41FC) — SETUP SUB-STATE:
;   Run $74DF and $4B4A (layout/data prep), advance $D9EC → state 3,
;   and reset the two-byte sub-state cursor $D9ED/$D9EE to 0.
.lbl_41FC:
    CALL $74DF                             ; $41FC [CD DF 74]
    CALL $4B4A                             ; $41FF [CD 4A 4B]
    LD HL,$D9EC                            ; $4202 [21 EC D9]
    INC (HL)                               ; $4205 [34]         ; advance → state 3
    XOR A                                  ; $4206 [AF]
    LD ($D9ED),A                           ; $4207 [EA ED D9]  ; → WRAM[$D9ED]  reset sub-cursor lo
    XOR A                                  ; $420A [AF]
    LD ($D9EE),A                           ; $420B [EA EE D9]  ; → WRAM[$D9EE]  reset sub-cursor hi
