; STATE 3 ($420F) — POPULATE LIST:
;   Advance to state 4, clear display index $C8DA, prep via $7555/$425B,
;   zero the 8-byte block at $DB42, then walk $DB74 entries of the
;   record array at $DD03 (loop continues below).
.lbl_420F:
    LD HL,$D9EC                            ; $420F [21 EC D9]
    INC (HL)                               ; $4212 [34]         ; advance → state 4
    XOR A                                  ; $4213 [AF]
    LD ($C8DA),A                           ; $4214 [EA DA C8]  ; → WRAM[$C8DA]  reset display idx
