    LD B,A                                 ; $423C [47]
    LD C,$04                               ; $423D [0E 04]
    LD HL,$DD07                            ; $423F [21 07 DD]
    CALL $4246                             ; $4242 [CD 46 42]
    RET                                    ; $4245 [C9]
; helper $4246 — clamp record nibbles:
;   For B monster slots starting at C, look up each via ROM0 $3374.
;   If found (no carry): keep low nibble only ($0F mask).
;   If not found (carry): force high nibbles ($E0). Writes back in place.
.lbl_4246:
    LD A,C                                 ; $4246 [79]
    CALL $3374                             ; $4247 [CD 74 33]  ; ROM0 $3374  (slot lookup)
    JR C,$4252                             ; $424A [38 06]
    LD A,(HL)                              ; $424C [7E]
    AND $0F                                ; $424D [E6 0F]
