    OR $E0                                 ; $4253 [F6 E0]
    LDI (HL),A                             ; $4255 [22]
.lbl_4256:
    INC C                                  ; $4256 [0C]
    DEC B                                  ; $4257 [05]
    JR NZ,$4246                            ; $4258 [20 EC]
    RET                                    ; $425A [C9]
; helper $425B — build active-monster table at WRAM[$DCEC]:
;   Scans all 8 battle slots (B=8). For each slot that exists (ROM0 $3374),
;   has flag bit2 set ($DB06 record), is not disabled (bit7 of $C1CD entry)
;   and not hidden (bit6 of $DD03 entry) → writes a 1-byte active marker;
;   otherwise writes the $FF/$FF "empty" sentinel. Produces the per-slot
;   status array consumed by the display states.
.lbl_425B:
    LD DE,$DCEC                            ; $425B [11 EC DC]  ; dest = active-monster table
    LD BC,$0800                            ; $425E [01 00 08]  ; B=8 slots, C=0 start
.lbl_4261:
