    ADC A,H                                ; $427A [8C]
    LD H,A                                 ; $427B [67]
    BIT 7,(HL)                             ; $427C [CB 7E]
    JR NZ,$4294                            ; $427E [20 14]
    LD A,C                                 ; $4280 [79]
    LD HL,$DD03                            ; $4281 [21 03 DD]
    ADD A,L                                ; $4284 [85]
