; STATE 4 ($429F) — sub-render step:
;   Jumps to $42B5: call $5017 (draw/refresh sub-panel), then reset the
;   sub-cursor $D9ED to 0. Stays in state 4 (no INC of $D9EC here).
.lbl_429F:
    JR,$42B5                               ; $429F [18 14]

; Presentation helper: calls two shared setup routines ($6E16, $7014)
;   then branches on WRAM[$DA88] (result/outcome flag):
;     $DA88==0 → $7076 (win/success path?)
;     $DA88≠0 → $707C (loss/other-outcome path?)
Bank80_fn3:  ; $42A1
    CALL $6E16                             ; $42A1 [CD 16 6E]
    CALL $7014                             ; $42A4 [CD 14 70]
    LD A,($DA88)                           ; $42A7 [FA 88 DA]  ; WRAM[$DA88]
    OR A                                   ; $42AA [B7]
