    LD ($D9ED),A                           ; $42B9 [EA ED D9]  ; → WRAM[$D9ED]
    RET                                    ; $42BC [C9]
; STATE 5 ($42BD) — hand off to sub-screen:
;   Wait until no message box ($C825==0), then run bank88 fn0 (which
;   drives its own sub-flow and advances state when it is done).
.lbl_42BD:
    LD A,($C825)                           ; $42BD [FA 25 C8]  ; WRAM[$C825]  message box up?
    OR A                                   ; $42C0 [B7]
