; STATE 6 ($42C7) — advance + normalize scene pointer:
;   Advance $D9EC → state 7, clear sub-cursor + counters
;   ($D9ED/$D9EE/$DD75/$DD6C/$DD68). If joypad active ($C86C≠0), pass the
