; STATE 7 ($4304) — draw main battle panel:
;   Run bank82 fn0 (render), then $707C + $6CEF (OAM / sprite update).
;   This label is also fallen-into from state 6. When the sequencer has
;   actually reached step 8, arm a 5-frame settle delay in $DA33.
.lbl_4304:
