;   look up the message's data pointer (table at $DA03, indexed by id-4),
;   stash it in $DA12:DA13, and dispatch it via bank20 fn6 + bank81 fn14.
.lbl_4620:
    LD A,($D9F4)                           ; $4620 [FA F4 D9]  ; WRAM[$D9F4]  anim counter
