; ==============================================================
; STATE 9 ($4D05) — DAMAGE RESOLUTION  (nested 6-step machine on $D9ED)
; ==============================================================
;   This resolves EVERY monster's action for the round, one actor at a
;   time. Two counters cooperate:
;     $DB88 = ACTOR ITERATOR  — which battle slot (0..7) is being resolved
;     $D9ED = PER-ACTOR STEP  — where we are in that actor's pipeline (0..5)
;   The pipeline runs sub1→sub2→sub3→sub4→sub5, and sub5 either INCs $DB88
;   and loops back to sub1 for the NEXT actor, or (when all 8 are done)
;   ends the whole state. Reached via JP $4D05 at the end of state 8.
;
;   The steps differ like a damage-dealing pipeline stage-by-stage:
;
;   sub 0 ($4D15) SETUP (runs once, not per-actor):
;       Clear per-monster status/flag bits across all 8 records at $DB00+
;       (RES 4/6/7, mask nibbles). Reset $DB88=0 so scanning starts at
;       slot 0; clear $D9F2/$D9F3. Advance $D9ED→1, fall into sub 1.
;
;   sub 1 ($4D6A) SELECT ACTOR:
;       Advance $D9ED→2. Check slot $DB88 exists via ROM0 $3374.
;       If no valid actor (carry) → $D9ED=5, jump to sub 5 (skip this one).
;       Else fall into sub 2.
;
;   sub 2 ($4D7E) COMPUTE EFFECT:
;       Advance $D9ED→3. Read the actor's action record ($DB07): top bits
;       ($C0) = effect kind, low bits ($3F) = amount. Decide heal vs damage
;       → indicator sprite $DB4C = $E1 (heal) or $E2 (damage), scale the
;       value (ROM0 $21DC) and stash the HP delta in $DB56/$DB57, draw the
;       damage/heal number, and arm a 5-frame delay in $DA33.
;       (No-effect / status-only paths short-circuit to sub 5.)
;
;   sub 3 ($4E5B) ANIMATE + APPLY HP:
;       Tick the $DA33 delay each frame (animating). When it hits 0,
;       advance $D9ED→4 and actually apply the change: subtract the delta
;       from the target's HP (16-bit table at $DBA3, indexed by slot),
;       clamp at 0. If HP reached 0 → DEATH path ($4EB2): mirror slot to
;       $DB89, bankcall bank88 fn1 (faint anim) + bank81 fn3, and queue the
;       "defeated" message in $DD61.
;
;   sub 4 ($4EF4) CHECK BATTLE END:
;       Advance $D9ED→5. Scan one side's 3 slots ($DB88 bit2 picks the
;       side) via ROM0 $3374 counting survivors. If a whole side is wiped
;       → set $DB55=done and FORCE the outer $D9EC=$0A (state 10 RESULT):
;       battle is over, skip the rest. Otherwise fall into sub 5.
;
;   sub 5 ($4F65) NEXT ACTOR / FINISH:
;       INC $DB88. If <8 and the slot is valid → $D9ED=1, JP $4D6A
;       (loop back to sub 1 for the next actor's action).
;       When $DB88 reaches 8 (all actors resolved) → rebuild the turn/
;       order lists at $DD13, then set outer $D9EC=$03 (back to state 3
;       POPULATE) to run the NEXT round.
;
;   NET: sub0 preps once; sub1-5 form a loop over actors; the state exits
;   to $D9EC=3 (next round) normally, or $D9EC=$0A (results) if one side
;   has been wiped out.
; --------------------------------------------------------------
.lbl_4D05:
    LD A,($D9ED)                           ; $4D05 [FA ED D9]  ; WRAM[$D9ED]  sub-step (0..5)
    RST $00                                ; $4D08 [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (6 sub-steps, keyed by WRAM[$D9ED]):
    DW $4D15    ; $4D09 [15 4D]  sub 0 — SETUP: clear status bits, $DB88=0
    DW $4D6A    ; $4D0B [6A 4D]  sub 1 — SELECT ACTOR (slot exists?)
    DW $4D7E    ; $4D0D [7E 4D]  sub 2 — COMPUTE EFFECT (heal/damage amount)
    DW $4E5B    ; $4D0F [5B 4E]  sub 3 — ANIMATE + APPLY HP (death handling)
    DW $4EF4    ; $4D11 [F4 4E]  sub 4 — CHECK BATTLE END (side wiped?)
    DW $4F65    ; $4D13 [65 4F]  sub 5 — NEXT ACTOR / FINISH round
; --- sub 0: SETUP — clear all monsters' per-turn status/flag bits ---
.lbl_4D15:
    LD HL,$DB00                            ; $4D15 [21 00 DB]
    RES 4,(HL)                             ; $4D18 [CB A6]
    RES 6,(HL)                             ; $4D1A [CB B6]
    INC HL                                 ; $4D1C [23]
    RES 4,(HL)                             ; $4D1D [CB A6]
    RES 6,(HL)                             ; $4D1F [CB B6]
    INC HL                                 ; $4D21 [23]
    LD B,$08                               ; $4D22 [06 08]
.lbl_4D24:
    INC HL                                 ; $4D24 [23]
    INC HL                                 ; $4D25 [23]
    RES 7,(HL)                             ; $4D26 [CB BE]
    INC HL                                 ; $4D28 [23]
    INC HL                                 ; $4D29 [23]
    LD A,(HL)                              ; $4D2A [7E]
    RRCA                                   ; $4D2B [0F]
    AND $55                                ; $4D2C [E6 55]
    LDI (HL),A                             ; $4D2E [22]
    LD A,(HL)                              ; $4D2F [7E]
    AND $30                                ; $4D30 [E6 30]
    CALL NZ,$4D5F                          ; $4D32 [C4 5F 4D]
    INC HL                                 ; $4D35 [23]
    LD A,(HL)                              ; $4D36 [7E]
