    LDI (HL),A                             ; $4D3B [22]
    DEC B                                  ; $4D3C [05]
    JR NZ,$4D24                            ; $4D3D [20 E5]
    LD B,$08                               ; $4D3F [06 08]
    XOR A                                  ; $4D41 [AF]
