    LDI (HL),A                             ; $4D49 [22]
    LD A,(HL)                              ; $4D4A [7E]
    AND $03                                ; $4D4B [E6 03]
    LDI (HL),A                             ; $4D4D [22]
    LD HL,$D9ED                            ; $4D4E [21 ED D9]
    INC (HL)                               ; $4D51 [34]
    XOR A                                  ; $4D52 [AF]
    LD ($DB88),A                           ; $4D53 [EA 88 DB]  ; → WRAM[$DB88]
    LD ($D9F2),A                           ; $4D56 [EA F2 D9]  ; → WRAM[$D9F2]
    LD ($D9F3),A                           ; $4D59 [EA F3 D9]  ; → WRAM[$D9F3]
    JR,$4D6A                               ; $4D5C [18 0C]
    RET                                    ; $4D5E [C9]
.lbl_4D5F:
    LD A,(HL)                              ; $4D5F [7E]
    AND $CF                                ; $4D60 [E6 CF]
    LD E,A                                 ; $4D62 [5F]
