; --- sub 3: ANIMATE + APPLY HP — run the delay, then subtract HP (death?) ---
.lbl_4E5B:
    LD A,($DA33)                           ; $4E5B [FA 33 DA]  ; frame-delay counter
    OR A                                   ; $4E5E [B7]
    JR Z,$4E6D                             ; $4E5F [28 0C]      ; delay elapsed → apply HP
    DEC A                                  ; $4E61 [3D]
    LD ($DA33),A                           ; $4E62 [EA 33 DA]  ; → WRAM[$DA33]
    OR A                                   ; $4E65 [B7]
    RET NZ                                 ; $4E66 [C0]
    LD A,$FD                               ; $4E67 [3E FD]
    CALL $4CF9                             ; $4E69 [CD F9 4C]
    RET                                    ; $4E6C [C9]
.lbl_4E6D:
    LD HL,$D9ED                            ; $4E6D [21 ED D9]
    INC (HL)                               ; $4E70 [34]
    ; ---- APPLY HP DAMAGE: curHP[slot] = max(0, curHP - damage) ----
    ;   $DBA3 = wBattleCurHP (working current-HP array, from record +$50).
    ;   Damage amount is in $DB56/$DB57, computed earlier this action:
    ;     - NORMAL ATTACK: hit strength is a TIERED function of ATTACK vs
    ;       DEFENSE (bank88 $67BA / bank87 $5F23): $DD26 = 20 + 10 per
    ;       DEFENSE-multiple the attacker's ATTACK clears (cap 255). So a
    ;       normal attack DOES use the monster's attack stat vs the target's
    ;       defense. (See wPhysAtkStrength $DD26 / bank87.asm note.)
    ;     - SPELL: fixed power from the spell record (bank84).
    ;     - %-HP effect: a fraction of the target's max HP (sub 2, $33A9).
    LD A,($DB88)                           ; $4E71 [FA 88 DB]  ; target slot
    LD HL,$DBA3                            ; $4E74 [21 A3 DB]  ; wBattleCurHP base
    ADD A,A                                ; $4E77 [87]        ; slot*2 (16-bit entries)
    ADD A,L                                ; $4E78 [85]
    LD L,A                                 ; $4E79 [6F]
    LD A,$00                               ; $4E7A [3E 00]
    ADC A,H                                ; $4E7C [8C]
    LD H,A                                 ; $4E7D [67]        ; HL = &curHP[slot]
    PUSH HL                                ; $4E7E [E5]
    LDI A,(HL)                             ; $4E7F [2A]        ; \ HL = current HP (16-bit LE)
    LD H,(HL)                              ; $4E80 [66]        ; /
    LD L,A                                 ; $4E81 [6F]
    LD A,($DB56)                           ; $4E82 [FA 56 DB]  ; \ BC = damage amount
    LD C,A                                 ; $4E85 [4F]        ; |
    LD A,($DB57)                           ; $4E86 [FA 57 DB]  ; |
    LD B,A                                 ; $4E89 [47]        ; /
    CALL $3314                             ; $4E8A [CD 14 33]  ; ROM0 $3314: 16-bit compare HP vs damage
    JR Z,$4E99                             ; $4E8D [28 0A]     ; HP == damage → floor to 0
    JR C,$4E99                             ; $4E8F [38 08]     ; HP  < damage → floor to 0 (faint)
    LD A,L                                 ; $4E91 [7D]        ; \ BC = HP - damage
    SUB C                                  ; $4E92 [91]        ; |
    LD C,A                                 ; $4E93 [4F]        ; |
    LD A,H                                 ; $4E94 [7C]        ; |
    SBC A,B                                ; $4E95 [98]        ; |
    LD B,A                                 ; $4E96 [47]        ; /
    JR,$4E9C                               ; $4E97 [18 03]
.lbl_4E99:
    LD BC,$0000                            ; $4E99 [01 00 00]  ; HP floored to 0 (monster faints)
.lbl_4E9C:
    POP HL                                 ; $4E9C [E1]
    LD A,C                                 ; $4E9D [79]        ; \ write new HP back to curHP[slot]
    LDI (HL),A                             ; $4E9E [22]        ; |
    LD (HL),B                              ; $4E9F [70]        ; /
    LD A,B                                 ; $4EA0 [78]
