; ==============================================================
; COMMAND PHASE — "pick your monsters' actions" ($5017)
; ==============================================================
;   Entered from fn2 state 4 ($42B5). Runs the whole "choose a command
;   for each of your monsters this turn" flow. It keeps its own step
;   counter in WRAM[$D9F4] and RST $00-dispatches to 11 states below.
;   (Called every frame; each state does one frame of work and usually
;    INC's $D9F4 to advance — some wait for input or a message.)
;
;   Related WRAM:
;     $D9F4  this machine's state index (0-10)
;     $D9F5  a sub-step used inside states 3/7 (nested machines)
;     $C8DA  the command cursor / chosen command (bit7 = "confirmed")
;     $C8DD  chosen target / actor slot
;     $C1C0  first selectable monster slot; $DB61 default command
;     $DB88/$DB89  counts of usable party monsters (attackers / total)
;     $C863 bit1  which side we are (player-1 vs player-2)
;     $C86C  link-battle connected flag; $C86E link handshake byte
;
;   State overview:
;     0 $5031  INIT  — open command window, count usable monsters, pick
;                      defaults, set per-monster "unselected" bits
;     1 $50ED  DRAW  — render the command menu + cursor, then → state 2
;     2 $5114  INPUT — read d-pad/A to pick a top-level command
;                      (Start toggles the help/info page)
;     3 $51EE  SUB-INPUT — run the chosen command's own handler
;                      (Attack/Skill/Defend/Item/Flee), dispatched on $C8DA
;     4 $5215  COMMIT — build this turn's action-order table ($C180)
;     5 $525E  SYNC   — raise link sync flag $C873 (link battle only)
;     6 $526E  PACK   — assemble our chosen action into the packet at
;                      $C1DA/$C1EA (pointers in $C871/$C874/$C86F)
;     7 $5301  EXCHANGE — wait for the partner, copy their action packet
;                      into the side tables ($DD03/$DD07, $DCEC/$DCF4…)
;     8 $53A7  DONE   — cleanup, reset $D9F4, and advance the OUTER fn2
;                      state $D9EC (leaves command phase → execution)
;     9 $51E0  WAIT   — pause until message box $C825 clears, → state 1
;    10 $69C3  RESUME — restore $D9F4 from a saved slot ($DB5A) after a
;                      submenu detour
; --------------------------------------------------------------
; STATE TRANSITION FLOW ($D9F4):
;
;        +------------------------------------------------+
;        |                                                |
;   0 INIT -> 1 DRAW -> 2 INPUT -> 3 SUB-INPUT -> 4 COMMIT |
;            ^   ^         | |         |  |                 |
;            |   +---------+ |         |  | (select done)   v
;            |  (loop while  |         |  +------------> 5 SYNC
;            |   browsing)   |         |                    |
;            |               |         | (B = cancel)       v
;            |               |         +---------> 1 or 0  6 PACK
;            |     (skill w/  |                              |
;            |    no target)  v                             v
;            +------------- 9 WAIT                       7 EXCHANGE
;                     (msg clears -> 1)                     |
;                                                           v
;                                                        8 DONE
;                                                           |
;                                     reset $D9F4=0 + INC $D9EC
;                                                           |
;                                                           v
;                                         (leaves command phase ->
;                                          fn2 executes the turn)
;
; Exit conditions (verified from the $D9F4 writes in the code):
;   0 INIT    always                         -> 1     (INC $50BB)
;   1 DRAW    always                         -> 2     (INC $5112)
;   2 INPUT   A pressed (command chosen)      -> 3     (INC $5145)
;             skill chosen, no auto-target    -> 9     (LD A,$09 $51C5)
;             Start / d-pad / no A            -> 2     (RET, stay)
;   3 SUBINP  selection complete              -> 4     ($5410=4, INC $5758)
;             B = cancel                      -> 1 or 0 ($547F/$55E5/$60EA=1;
;                                                        $542A/$5442/$66B8/$6882=0)
;             navigating submenu              -> 3     (advances $D9F5, not $D9F4)
;   4 COMMIT  always                          -> 5     (INC $525C)
;   5 SYNC    always (link: raise $C873)      -> 6     (INC $526C)
;   6 PACK    (link: wait $C86E==1)           -> 7     (INC $52FF)
;   7 EXCH    (link: wait $C86E==$F0)         -> 8     (INC $53A5)
;   8 DONE    always; also INC outer $D9EC    -> 0     (LD A,$00 $53BE)  [EXIT]
;   9 WAIT    message box $C825 cleared       -> 1     (LD A,$01 $51E8)
;  10 RESUME  restore saved state             -> $DB5A (LD A,($DB5A) $69D1)
;
; Notes:
;   - The core is linear: 4->5->6->7->8 just INC every frame. States 5/6/7
;     only do real work in a LINK battle (they gate on the partner); in
;     single-player they pass straight through.
;   - The two "back" edges (state 2 self-loop, state 3 cancel -> 1/0) form
;     the browse/cancel loop back to the command menu.
;   - State 3 is itself a sub-machine keyed on $D9F5 (skill list / target
;     picker); it stays in state 3 until confirm (->4) or cancel (->1/0).
;   - State 10 is NOT reached by any $D9F4 write in this machine (nothing
;     loads $0A here). A submenu parks $D9F4=$0A externally and stashes the
;     real state in $DB5A; state 10 is the "return trampoline" back to it.
;   - Only state 8 touches the OUTER sequencer: it resets $D9F4=0 and
;     INCs $D9EC, handing control back to fn2 to execute the turn.
; --------------------------------------------------------------
.lbl_5017:
    LD A,($D9F4)                           ; $5017 [FA F4 D9]  ; command-phase state (0-10)
    RST $00                                ; $501A [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (11 states):
    DW $5031    ; $501B [31 50]  state 0  — INIT
    DW $50ED    ; $501D [ED 50]  state 1  — DRAW menu
    DW $5114    ; $501F [14 51]  state 2  — INPUT (pick command)
    DW $51EE    ; $5021 [EE 51]  state 3  — SUB-INPUT (command handler)
    DW $5215    ; $5023 [15 52]  state 4  — COMMIT order table
    DW $525E    ; $5025 [5E 52]  state 5  — link SYNC flag
    DW $526E    ; $5027 [6E 52]  state 6  — PACK our action
    DW $5301    ; $5029 [01 53]  state 7  — link EXCHANGE
    DW $53A7    ; $502B [A7 53]  state 8  — DONE → advance $D9EC
    DW $51E0    ; $502D [E0 51]  state 9  — WAIT for message
    DW $69C3    ; $502F [C3 69]  state 10 — RESUME after submenu
; STATE 0 ($5031) — INIT the command menu:
;   Open the window (bank85 fn6), zero $D9F4..+7, point the tilemap at
;   $9800. Scan the 3-4 party slots: count those still able to act into
;   $DB88, remember the first selectable one in $C1C0, and set each
;   monster's "not yet chosen" bit (bit7 of $C1CD+). Also count via ROM0
;   $3374 into $DB89. Advance to state 1 and pick the default command
;   ($DB61) = first slot that has a usable skill.
.lbl_5031:
    LD HL,$5506                            ; $5031 [21 06 55]
    RST $10                                ; $5034 [D7]  ; bankcall → bank85 fn6
    XOR A                                  ; $5035 [AF]
    LD HL,$D9F4                            ; $5036 [21 F4 D9]
    LD BC,$0008                            ; $5039 [01 08 00]
    CALL $169A                             ; $503C [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    LD HL,$9800                            ; $503F [21 00 98]
    LD A,L                                 ; $5042 [7D]
    LD ($D9F8),A                           ; $5043 [EA F8 D9]  ; → WRAM[$D9F8]
    LD A,H                                 ; $5046 [7C]
    LD ($D9F9),A                           ; $5047 [EA F9 D9]  ; → WRAM[$D9F9]
    LD A,$FF                               ; $504A [3E FF]
    LD ($C1C0),A                           ; $504C [EA C0 C1]  ; → WRAM[$C1C0]
    LD BC,$0300                            ; $504F [01 00 03]
    LD A,($C86C)                           ; $5052 [FA 6C C8]  ; WRAM[$C86C]
    OR A                                   ; $5055 [B7]
    JR Z,$5062                             ; $5056 [28 0A]
    LD A,($C863)                           ; $5058 [FA 63 C8]  ; WRAM[$C863]
    BIT 1,A                                ; $505B [CB 4F]
    JR Z,$5062                             ; $505D [28 03]
    LD BC,$0304                            ; $505F [01 04 03]
.lbl_5062:
    LD D,$00                               ; $5062 [16 00]
.lbl_5064:
    LD A,C                                 ; $5064 [79]
    CALL $6AFA                             ; $5065 [CD FA 6A]
    JR C,$5081                             ; $5068 [38 17]
    LD A,C                                 ; $506A [79]
    LD HL,$DB02                            ; $506B [21 02 DB]
    CALL $333B                             ; $506E [CD 3B 33]  ; ROM0 $333B
    BIT 4,(HL)                             ; $5071 [CB 66]
    JR NZ,$5081                            ; $5073 [20 0C]
    INC D                                  ; $5075 [14]
    LD A,($C1C0)                           ; $5076 [FA C0 C1]  ; WRAM[$C1C0]
    CP $FF                                 ; $5079 [FE FF]
