    LD BC,$0404                            ; $5089 [01 04 04]
    LD A,($C86C)                           ; $508C [FA 6C C8]  ; WRAM[$C86C]
    OR A                                   ; $508F [B7]
    JR Z,$509C                             ; $5090 [28 0A]
    LD A,($C863)                           ; $5092 [FA 63 C8]  ; WRAM[$C863]
