; STATE 1 ($50ED) — DRAW/refresh the command menu:
;   bank85 fn5 (draw window contents), redraw the battle panel
;   ($6E16/$7014/$707C), blit the command list ($6CB8), reset the cursor
;   blink ($6F10), draw the cursor at $C8DA using descriptor $519B ($6FD3),
;   DMA the tilemap ($6D56), then advance to state 2 (input).
.lbl_50ED:
    LD HL,$5505                            ; $50ED [21 05 55]
    RST $10                                ; $50F0 [D7]  ; bankcall → bank85 fn5
    CALL $6E16                             ; $50F1 [CD 16 6E]
    CALL $7014                             ; $50F4 [CD 14 70]
    CALL $707C                             ; $50F7 [CD 7C 70]
