    LD A,($C8DA)                           ; $5106 [FA DA C8]  ; WRAM[$C8DA]
    CALL $6FD3                             ; $5109 [CD D3 6F]
    CALL $6D56                             ; $510C [CD 56 6D]
    LD HL,$D9F4                            ; $510F [21 F4 D9]
    INC (HL)                               ; $5112 [34]
    RET                                    ; $5113 [C9]
; STATE 2 ($5114) — INPUT: choose a top-level command.
;   First checks Start ($C846 bit3): if pressed, toggle the help/info
;   page ($D9F3 between 0 and 3) and refresh it ($714F), then return.
;   Otherwise fall to $512D — the 2×2 command-cursor handler ($6EF6) plus
;   the A-button confirm (see the annotated block there). On confirm it
;   advances $D9F4 and, for the "skill" command, opens the skill/target
;   submenu (bank85 fn6).
.lbl_5114:
    LD A,($C846)                           ; $5114 [FA 46 C8]  ; edge buttons
    AND $08                                ; $5117 [E6 08]      ; Start pressed?
    JR Z,$512D                             ; $5119 [28 12]      ; no → cursor/confirm handler
    LD A,($D9F3)                           ; $511B [FA F3 D9]  ; help-page toggle
    OR A                                   ; $511E [B7]
    JR NZ,$5124                            ; $511F [20 03]
    INC A                                  ; $5121 [3C]
    JR,$5126                               ; $5122 [18 02]
.lbl_5124:
    LD A,$03                               ; $5124 [3E 03]
.lbl_5126:
    LD ($D9F3),A                           ; $5126 [EA F3 D9]  ; → WRAM[$D9F3]
    CALL $714F                             ; $5129 [CD 4F 71]
    RET                                    ; $512C [C9]
; TOP-LEVEL BATTLE COMMAND MENU (per active party monster):
;   Cursor lives in $C8DA (0-3, laid out as a 2×2 grid of commands).
;   $519B = the menu descriptor table passed to the grid navigator.
;   1) $6EF6 moves the cursor with the d-pad (Up/Down/Left/Right).
;   2) then A ($C846 bit0) confirms: play "confirm" SFX $59, advance the
;      turn state ($D9F4), latch the chosen command bit7 into $C8DA, clear
;      the sub-selection scratch ($C8DB+7 bytes), and branch by command:
;      command 1 → bankcall bank85 fn6 (opens the skill/target sub-menu).
.lbl_512D:
    LD DE,$519B                            ; $512D [11 9B 51]  ; menu descriptor
    LD HL,$C8DA                            ; $5130 [21 DA C8]  ; command cursor (0-3)
    CALL $6EF6                             ; $5133 [CD F6 6E]  ; d-pad → move cursor (2×2 grid)
    LD A,($C846)                           ; $5136 [FA 46 C8]  ; edge buttons
    BIT 0,A                                ; $5139 [CB 47]      ; A pressed (confirm)?
    JR Z,$519A                             ; $513B [28 5D]      ; no → wait next frame
    LD A,$59                               ; $513D [3E 59]
    CALL $1EFF                             ; $513F [CD FF 1E]  ; ROM0 $1EFF  (play confirm SFX $59)
    LD HL,$D9F4                            ; $5142 [21 F4 D9]
    INC (HL)                               ; $5145 [34]         ; advance turn sub-state
    XOR A                                  ; $5146 [AF]
    LD ($D9F5),A                           ; $5147 [EA F5 D9]  ; → WRAM[$D9F5]
    LD HL,$C8DA                            ; $514A [21 DA C8]
    SET 7,(HL)                             ; $514D [CB FE]
    LD HL,$C8DB                            ; $514F [21 DB C8]
    LD BC,$0007                            ; $5152 [01 07 00]
    LD A,$00                               ; $5155 [3E 00]
    CALL $169A                             ; $5157 [CD 9A 16]  ; memset(HL=dst,A=0,BC=n)
    LD A,($C8DA)                           ; $515A [FA DA C8]  ; WRAM[$C8DA]
    AND $0F                                ; $515D [E6 0F]
    CP $01                                 ; $515F [FE 01]
    RET NZ                                 ; $5161 [C0]
    LD HL,$5506                            ; $5162 [21 06 55]
    RST $10                                ; $5165 [D7]  ; bankcall → bank85 fn6
    XOR A                                  ; $5166 [AF]
    LD ($C8DD),A                           ; $5167 [EA DD C8]  ; → WRAM[$C8DD]
    LD A,($C863)                           ; $516A [FA 63 C8]  ; WRAM[$C863]
    BIT 1,A                                ; $516D [CB 4F]
    JR Z,$5176                             ; $516F [28 05]
    LD A,$04                               ; $5171 [3E 04]
    LD ($C8DD),A                           ; $5173 [EA DD C8]  ; → WRAM[$C8DD]
