    LD ($C8DD),A                           ; $517E [EA DD C8]  ; → WRAM[$C8DD]
    LD HL,$D9F5                            ; $5181 [21 F5 D9]
    INC (HL)                               ; $5184 [34]
    LD HL,$D9F5                            ; $5185 [21 F5 D9]
    INC (HL)                               ; $5188 [34]
