    RET                                    ; $51B8 [C9]
.lbl_51B9:
    CALL $6E16                             ; $51B9 [CD 16 6E]
    CALL $7014                             ; $51BC [CD 14 70]
    CALL $707C                             ; $51BF [CD 7C 70]
    LD HL,$0002                            ; $51C2 [21 02 00]
    LD A,$09                               ; $51C5 [3E 09]
    LD ($D9F4),A                           ; $51C7 [EA F4 D9]  ; → WRAM[$D9F4]
    LD A,L                                 ; $51CA [7D]
    LD ($C822),A                           ; $51CB [EA 22 C8]  ; → WRAM[$C822]
    LD A,H                                 ; $51CE [7C]
    LD ($C823),A                           ; $51CF [EA 23 C8]  ; → WRAM[$C823]
    LD HL,$4C00                            ; $51D2 [21 00 4C]
    RST $10                                ; $51D5 [D7]  ; bankcall → bank76 fn0
    LD DE,$31D6                            ; $51D6 [11 D6 31]
    CALL $6CB8                             ; $51D9 [CD B8 6C]
    CALL $6D56                             ; $51DC [CD 56 6D]
    RET                                    ; $51DF [C9]
; STATE 9 ($51E0) — WAIT for a message to finish:
;   A transient state other code jumps to; it blocks until the message
;   box $C825 clears, refreshes ($6E16), then drops back to state 1 (draw).
.lbl_51E0:
    LD A,($C825)                           ; $51E0 [FA 25 C8]  ; message box active?
    OR A                                   ; $51E3 [B7]
    RET NZ                                 ; $51E4 [C0]         ; still up → wait
    CALL $6E16                             ; $51E5 [CD 16 6E]
    LD A,$01                               ; $51E8 [3E 01]
    LD ($D9F4),A                           ; $51EA [EA F4 D9]  ; → state 1 (redraw)
    RET                                    ; $51ED [C9]
; STATE 3 ($51EE) — SUB-INPUT: run the chosen command's handler.
;   Same Start→help-toggle guard as state 2, then dispatches on the
;   confirmed command in $C8DA (0-4) to that command's own routine:
;     0 $53C7 Attack (target select)   1 $541A Skill/spell
;     2 $5FB9 (command 2)              3 $6708 (command 3)
;     4 $5792 (command 4 — e.g. flee/tactics)
;   These sub-routines pick the target and set $D9F4 forward when done.
.lbl_51EE:
    LD A,($C846)                           ; $51EE [FA 46 C8]  ; edge buttons
    AND $08                                ; $51F1 [E6 08]      ; Start?
    JR Z,$5207                             ; $51F3 [28 12]      ; no → command dispatch
    LD A,($D9F3)                           ; $51F5 [FA F3 D9]  ; help-page toggle
    OR A                                   ; $51F8 [B7]
    JR NZ,$51FE                            ; $51F9 [20 03]
    INC A                                  ; $51FB [3C]
    JR,$5200                               ; $51FC [18 02]
.lbl_51FE:
    LD A,$03                               ; $51FE [3E 03]
.lbl_5200:
    LD ($D9F3),A                           ; $5200 [EA F3 D9]  ; → WRAM[$D9F3]
    CALL $714F                             ; $5203 [CD 4F 71]
    RET                                    ; $5206 [C9]
.lbl_5207:
    LD A,($C8DA)                           ; $5207 [FA DA C8]  ; confirmed command (0-4)
    RST $00                                ; $520A [C7]  ; dispatch to command handler
    ; RST $00 table (5 command handlers):
    DW $53C7    ; $520B [C7 53]  cmd 0 — Attack / target-select
    DW $541A    ; $520D [1A 54]  cmd 1 — Skill / spell
    DW $5FB9    ; $520F [B9 5F]  cmd 2
    DW $6708    ; $5211 [08 67]  cmd 3
    DW $5792    ; $5213 [92 57]  cmd 4 — (flee / tactics)
