;   If the help page is open ($D9F3) close it first ($7257). Otherwise
;   (link battle) copy this side's monster-order list — $CACD or $CD21 by
;   side flag $C863 bit1 — into $C180 via ROM0 $106C, play a sound, redraw,
;   DMA. Then advance $D9F4.
.lbl_5215:
    LD A,($D9F3)                           ; $5215 [FA F3 D9]  ; WRAM[$D9F3]
    OR A                                   ; $5218 [B7]
    JR Z,$5224                             ; $5219 [28 09]
