    RET                                    ; $525D [C9]
; STATE 5 ($525E) — link SYNC: if connected ($C86C), raise the sync flag
;   $C873=1 so the serial driver (bank3) knows we're ready to exchange.
;   Then advance $D9F4. (Single-player: just advances.)
.lbl_525E:
    LD A,($C86C)                           ; $525E [FA 6C C8]  ; connected?
    OR A                                   ; $5261 [B7]
    JR Z,$5269                             ; $5262 [28 05]
    LD A,$01                               ; $5264 [3E 01]
    LD ($C873),A                           ; $5266 [EA 73 C8]  ; sync flag = 1
.lbl_5269:
    LD HL,$D9F4                            ; $5269 [21 F4 D9]
    INC (HL)                               ; $526C [34]
    RET                                    ; $526D [C9]
; STATE 6 ($526E) — PACK our chosen action into the transfer packet.
;   Single-player ($C86C==0): skip straight to $52FC (just advance).
;   Link battle: wait for handshake $C86E==1, then copy this side's
;   order/action records (from $DD03/$DD07 and $DCEC/$DCF4 depending on
;   side) into the packet buffer at $C1DA, set the packet length/pointers
;   ($C871=$10, $C874:$C875→$C1DA, $C86F:$C870→$C1EA) and mark it ready
;   ($C873=$FF). This is the outgoing data the serial driver ships to the
;   other console.
.lbl_526E:
    LD A,($C86C)                           ; $526E [FA 6C C8]  ; connected?
    OR A                                   ; $5271 [B7]
    JP Z,$52FC                             ; $5272 [CA FC 52]  ; single-player → just advance
    LD A,($C86E)                           ; $5275 [FA 6E C8]  ; link handshake byte
