    LD A,$00                               ; $5BC3 [3E 00]
    ADC A,H                                ; $5BC5 [8C]
    LD H,A                                 ; $5BC6 [67]        ; HL = &curMP[slot]
    LDI A,(HL)                             ; $5BC7 [2A]        ; \ HL = current MP (16-bit LE)
    LD H,(HL)                              ; $5BC8 [66]        ; /
    LD L,A                                 ; $5BC9 [6F]
    CALL $3314                             ; $5BCA [CD 14 33]  ; ROM0 $3314: compare curMP vs cost
