; STATE 10 ($69C3) — RESUME after a submenu detour.
;   When a command opens a nested menu (skill/item), it saves a return
;   pointer in $DB58:$DB59 and the state to resume in $DB5A, then parks
;   $D9F4 here. This state restores the display ($66FE / $66E7 with the
;   saved pointer) and jumps $D9F4 back to the saved state to continue.
.lbl_69C3:
    CALL $66FE                             ; $69C3 [CD FE 66]  ; restore cursor/display
    LD A,($DB58)                           ; $69C6 [FA 58 DB]  ; saved return pointer lo
    LD L,A                                 ; $69C9 [6F]
    LD A,($DB59)                           ; $69CA [FA 59 DB]  ; saved return pointer hi
    LD H,A                                 ; $69CD [67]
    CALL $66E7                             ; $69CE [CD E7 66]  ; redraw with saved context
    LD A,($DB5A)                           ; $69D1 [FA 5A DB]  ; saved resume-state
    LD ($D9F4),A                           ; $69D4 [EA F4 D9]  ; → jump back to that state
    RET                                    ; $69D7 [C9]

