; ==============================================================
; BATTLE COMMAND-MENU CURSOR ENGINE   ($6EBF … $6F14)
; ==============================================================
;   This is where the player's d-pad + A input actually moves the
;   selection cursor on the battle screen and confirms an action.
;
;   Joypad bytes (produced by ROM0 JoypadProcess @ $1737):
;     $C846 = newly-pressed this frame (edge, NO auto-repeat) → used for A/B
;     $C847 = "effective" input = newly-pressed + auto-repeat (20-frame
;             initial delay, then every 6 frames) → used for DIRECTIONS
;             so holding a direction scrolls the cursor.
;   Button bit layout (both bytes):
;     bit0 A  bit1 B  bit2 Select  bit3 Start
;     bit4 Right  bit5 Left  bit6 Up  bit7 Down
;
;   HL → the cursor variable (the caller passes it, e.g. $C8DA for the
;   top-level command menu). Bit 7 of that variable = "confirmed" flag.
;
;   There are TWO navigator flavours sharing the tail at $6EDF/$6EE8:
;     • LINEAR list ($6EBF, this block): B = item count. Up decrements,
;       Down increments, with wrap-around (0..B-1). Used for vertical
;       lists (skill list, item list, target list…).
;     • 2×2 GRID ($6EF6, below): Up/Down flips cursor bit0, Left/Right
;       flips cursor bit1 — the four top-level battle commands.
; --------------------------------------------------------------
; LINEAR navigator: UP = previous entry (wrap to bottom)
.lbl_6EBF:
    RES 7,(HL)                             ; $6EBF [CB BE]      ; clear "confirmed" bit
    LD A,($C847)                           ; $6EC1 [FA 47 C8]  ; directions (with repeat)
    BIT 6,A                                ; $6EC4 [CB 77]      ; UP pressed?
    JR Z,$6ED1                             ; $6EC6 [28 09]      ; no → check DOWN
    LD A,(HL)                              ; $6EC8 [7E]         ; cursor index
    DEC A                                  ; $6EC9 [3D]         ; move up one
    CP B                                   ; $6ECA [B8]
    JR C,$6EDF                             ; $6ECB [38 12]      ; in range → store
    DEC B                                  ; $6ECD [05]         ; underflow → wrap to last (B-1)
    LD A,B                                 ; $6ECE [78]
    JR,$6EDF                               ; $6ECF [18 0E]
; LINEAR navigator: DOWN = next entry (wrap to top)
.lbl_6ED1:
    LD A,($C847)                           ; $6ED1 [FA 47 C8]  ; directions (with repeat)
    BIT 7,A                                ; $6ED4 [CB 7F]      ; DOWN pressed?
    JR Z,$6EE8                             ; $6ED6 [28 10]      ; no direction → just check A
    LD A,(HL)                              ; $6ED8 [7E]
    INC A                                  ; $6ED9 [3C]         ; move down one
    CP B                                   ; $6EDA [B8]
    JR C,$6EDF                             ; $6EDB [38 02]      ; in range → store
    LD A,$00                               ; $6EDD [3E 00]      ; past end → wrap to 0
.lbl_6EDF:
    LD (HL),A                              ; $6EDF [77]         ; write updated cursor index
.lbl_6EE0:
    XOR A                                  ; $6EE0 [AF]
    LD ($D9FB),A                           ; $6EE1 [EA FB D9]  ; → WRAM[$D9FB]
    PUSH HL                                ; $6EE4 [E5]
    PUSH DE                                ; $6EE5 [D5]
    POP DE                                 ; $6EE6 [D1]
    POP HL                                 ; $6EE7 [E1]
; SHARED TAIL — confirm with A, then redraw the cursor highlight.
.lbl_6EE8:
    LD A,($C846)                           ; $6EE8 [FA 46 C8]  ; edge buttons (no repeat)
    BIT 0,A                                ; $6EEB [CB 47]      ; A pressed?
    JR Z,$6EF1                             ; $6EED [28 02]
    SET 7,(HL)                             ; $6EEF [CB FE]      ; A → set bit7 = "action chosen"
.lbl_6EF1:
    LD A,(HL)                              ; $6EF1 [7E]         ; current cursor value
    CALL $6F15                             ; $6EF2 [CD 15 6F]  ; redraw cursor/highlight sprite
    RET                                    ; $6EF5 [C9]
; 2×2 GRID navigator (top-level battle commands): Up/Down = row (bit0),
;   Left/Right = column (bit1). Entered by the command-select state via
;   CALL $6EF6 with HL = $C8DA (see $5133).
.lbl_6EF6:
    RES 7,(HL)                             ; $6EF6 [CB BE]      ; clear "confirmed" bit
    LD A,($C847)                           ; $6EF8 [FA 47 C8]  ; directions (with repeat)
    AND $C0                                ; $6EFB [E6 C0]      ; Up OR Down?
    JR Z,$6F04                             ; $6EFD [28 05]
    LD A,(HL)                              ; $6EFF [7E]
    XOR $01                                ; $6F00 [EE 01]      ; flip row bit (toggle top/bottom)
    JR,$6EDF                               ; $6F02 [18 DB]      ; store + check A
.lbl_6F04:
    LD A,($C847)                           ; $6F04 [FA 47 C8]  ; directions (with repeat)
    AND $30                                ; $6F07 [E6 30]      ; Left OR Right?
    JR Z,$6EE8                             ; $6F09 [28 DD]      ; no direction → just check A
    LD A,(HL)                              ; $6F0B [7E]
    XOR $02                                ; $6F0C [EE 02]      ; flip column bit (toggle left/right)
    JR,$6EDF                               ; $6F0E [18 CF]      ; store + check A
.lbl_6F10:
